/**
 * Monday.com Node - Version 2
 * Discriminator: resource=item, operation=bulkImport
 */


// Helper types for special n8n fields
type ResourceMapperField = { id?: string; displayName?: string; required?: boolean; defaultMatch?: boolean; display?: boolean; type?: string; canBeUsedToMatch?: boolean; [key: string]: unknown };
type ResourceMapperCommon = { matchingColumns?: string[]; cachedResultName?: string; [key: string]: unknown };
type ResourceMapperValue = ResourceMapperCommon & { mappingMode: string; value?: null | Record<string, unknown>; schema?: ResourceMapperField[] };

interface Credentials {
  mondayComApi: CredentialReference;
  mondayComOAuth2Api: CredentialReference;
}

/** Create or upsert up to 10,000 items in one asynchronous CSV import job — all input items become one job */
export type MondayComV2ItemBulkImportParams = {
  resource: 'item';
  operation: 'bulkImport';
  authentication?: 'accessToken' | 'oAuth2' | Expression<string>;
/**
 * The board to operate on
 * @searchListMethod searchBoards
 * @default {"mode":"list","value":""}
 */
    boardId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * The group newly created items are added to; leave empty for the board's top group. With Upsert/Skip matching, matching is board-wide — this only places NEW items. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
 * @loadOptionsMethod getBoardGroups
 */
    bulkImportGroupId?: string | Expression<string>;
/**
 * Which import mutation to use
 * @default ingest
 */
    bulkImportType?: 'backfill' | 'ingest';
/**
 * Where the import rows come from
 * @default mapped
 */
    bulkImportSource?: 'file' | 'mapped';
/**
 * Columns
 * @displayOptions.show { bulkImportSource: ["mapped"] }
 * @default {"mappingMode":"defineBelow","value":null}
 */
    bulkImportColumns?: ResourceMapperValue;
/**
 * Input Binary Field
 * @hint The name of the input binary field containing the CSV file to import
 * @displayOptions.show { bulkImportSource: ["file"] }
 * @default data
 */
    bulkImportBinaryPropertyName?: string | Expression<string>;
/**
 * How to handle rows whose match column value already exists on the board. Not available for multi-level hierarchy files (they always create).
 * @displayOptions.show { bulkImportType: ["ingest"] }
 * @default none
 */
    bulkImportOnMatch?: 'none' | 'SKIP' | 'UPSERT' | Expression<string>;
/**
 * The column existing items are matched on (board-wide). If several rows share a match value, only the last row is applied; if several items match, the most recently created one is updated. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
 * @loadOptionsMethod getBulkImportMatchColumns
 * @displayOptions.show { bulkImportType: ["ingest"], bulkImportOnMatch: ["UPSERT", "SKIP"] }
 * @required when the displayOptions conditions above match
 */
    bulkImportMatchColumnId?: string | Expression<string>;
/**
 * Whether to wait for the import job to finish (polling every 10 seconds, up to Max Wait Time) and return its result. When off, save the job ID and poll manually with Get Bulk Import Status every 10 seconds.
 * @default true
 */
    bulkImportWait?: boolean | Expression<boolean>;
/**
 * Options
 * @default {}
 */
    bulkImportOptions?: {
    /** Whether to also output one item per imported row from monday's import report (serial number, status, item ID, error) — useful for routing failed rows. Requires Wait for Completion.
     * @default false
     */
    includeRowResults?: boolean | Expression<boolean>;
    /** How long to wait for the job to finish, in seconds, before giving up with an error (the job itself keeps running on monday's side)
     * @default 1800
     */
    maxWaitTime?: number | Expression<number>;
  };
};

export type MondayComV2ItemBulkImportNode = {
  type: 'n8n-nodes-base.mondayCom';
  version: 2;
  config: NodeConfig<MondayComV2ItemBulkImportParams> & { credentials?: Credentials };
};